cat > /tmp/fix.mjs <<'EOF'
const exp = JSON.parse(await import("node:fs").then(m=>m.readFileSync("tests/expected.json","utf8")));
const cands = {
  A: [v=>(v+Math.floor(v/3)+1)%997, v=>(v+Math.floor(v/3))%997, v=>(v+Math.floor(v/3)-1)%997, v=>(v+Math.floor((v+1)/3)+1)%997],
  B: (i)=>[v=>v^(((i+1)*7)%64), v=>v^((i*7)%64), v=>v^(((i-1)*7)%64)],
  C: (i)=>[v=>(v*3-i+1)%991, v=>(v*3-i)%991, v=>(v*3-i-1)%991, v=>(v*3+i)%991, v=>(v*3+i-1)%991],
  D: [v=>(v*2+2)%1000, v=>(v*2+1)%1000, v=>(v*2)%1000],
};
let v = exp.input;
for (let i=1;i<=32;i++){
  const want = exp.stages[i-1];
  const r = i%4;
  const list = r===1?cands.A : r===2?cands.B(i) : r===3?cands.C(i) : cands.D;
  const hits = list.map(f=>f(v)).map((x,idx)=>x===want?idx:-1).filter(x=>x>=0);
  console.log(i, "in",v,"want",want,"cand hits:",hits);
  v = want; // assume unique-enough; chain proceeds with expected
}
EOF
